import{_ as l,a0 as o,w as n,s as p,I as e,x as r,a1 as s,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"用 InDesign 的開源替代方案 Scribus 設計書籍封面 | LCTT x X-CMD","titleTemplate":false,"description":"用 InDesign 的開源替代方案 Scribus 設計書籍封面 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 InDesign 的開源替代方案 Scribus 設計書籍封面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 InDesign 的開源替代方案 Scribus 設計書籍封面 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200902 Design a book cover with an open source alternative to InDesign","title":"用 InDesign 的開源替代方案 Scribus 設計書籍封面","tag":"202009","desc":""},"relativePath":"202009/20200902 Design a book cover with an open source alternative to InDesign.md","filePath":"[post].md"}'),b={name:"202009/20200902 Design a book cover with an open source alternative to InDesign.md"};function d(m,t,g,f,y,D){const u=o("Link");return n(),p("div",null,[t[23]||(t[23]=e("h1",{id:"用-indesign-的開源替代方案-scribus-設計書籍封面",tabindex:"-1"},[r("用 InDesign 的開源替代方案 Scribus 設計書籍封面 "),e("a",{class:"header-anchor",href:"#用-indesign-的開源替代方案-scribus-設計書籍封面","aria-label":"Permalink to “用 InDesign 的開源替代方案 Scribus 設計書籍封面”"},"​")],-1)),t[24]||(t[24]=e("blockquote",null,[e("p",null,"使用開源的出版軟件 Scribus 來製作你的下一本自出版書籍的封面。")],-1)),t[25]||(t[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/16/213714ppvfzm6idv9nnynp.jpg",alt:""})],-1)),e("p",null,[t[2]||(t[2]=r("我最近寫完了一本關於 ",-1)),s(u,{href:"https://opensource.com/article/20/8/c-programming-cheat-sheet"},{default:i(()=>[...t[0]||(t[0]=[r("C 語言編程",-1)])]),_:1}),t[3]||(t[3]=r("的書，我通過 ",-1)),s(u,{href:"https://www.lulu.com/"},{default:i(()=>[...t[1]||(t[1]=[r("Lulu.com",-1)])]),_:1}),t[4]||(t[4]=r(" 自行出版。我已經用 Lulu 做了好幾個圖書項目，它是一個很棒的平台。今年早些時候，Lulu 做了一些改變，讓作者在創作圖書封面時有了更大的控制權。以前，你只需上傳一對大尺寸圖片作為書的封面和封底。現在，Lulu 允許作者上傳完全按照你的書的尺寸定製的 PDF。",-1))]),e("p",null,[t[6]||(t[6]=r("你可以使用 ",-1)),s(u,{href:"https://www.scribus.net/"},{default:i(()=>[...t[5]||(t[5]=[r("Scribus",-1)])]),_:1}),t[7]||(t[7]=r(" 這個開源頁面佈局程序來創建封面。下面是我的做法。",-1))]),t[26]||(t[26]=a('<h3 id="下載一個模板" tabindex="-1">下載一個模板 <a class="header-anchor" href="#下載一個模板" aria-label="Permalink to “下載一個模板”">​</a></h3><p>當你在 Lulu 上輸入圖書的信息時，最終會進入<ruby>設計<rt>Design</rt></ruby>欄。在該頁面的<ruby>設計封面<rt>Design Your Cover</rt></ruby>部分，你會發現一個方便的<ruby>下載模板<rt>Download Template</rt></ruby>按鈕，它為你的圖書封面提供了一個 PDF 模板。</p><p><img src="https://opensource.com/sites/default/files/uploads/lulu-download-template.jpg" alt="Lulu Design your Cover page" title="Lulu Design your Cover page"></p><p>下載此模板，它為你提供了在 Scribus 中創建自己的書籍封面所需的信息。</p><p><img src="https://opensource.com/sites/default/files/uploads/lulu-pdf-template.jpg" alt="Lulu&#39;s cover template" title="Lulu&#39;s cover template"></p><p>最重要的細節是：</p><ul><li><ruby>文件總尺寸（含出血）<rt>Total Document Size (with bleed)</rt></ruby></li><li><ruby>出血區（從裁切邊緣）<rt>Bleed area (from trim edge)</rt></ruby></li><li><ruby>書脊區<rt>Spine area</rt></ruby></li></ul><p><ruby>出血<rt>Bleed</rt></ruby>是一個印刷術語，在準備“印刷就緒”文件時，這個術語很重要。它與普通文件中的頁邊距不同。打印文件時，你會為頂部、底部和側面設置一個頁邊距。在大多數文檔中，頁邊距通常為一英寸左右。</p><p>但在印刷就緒的文件中，文檔的尺寸需要比成品書大一些，因為書籍的封面通常包括顏色或圖片，一直到封面的邊緣。為了創建這種設計，你要使顏色或圖片超出你的邊距，印刷廠就會把多餘的部分裁切掉，使封面縮小到準確的尺寸。因此，“裁切”就是印刷廠將封面精確地裁剪成相應尺寸。而“出血區”就是印刷廠裁掉的多餘部分。</p><p>如果你沒有出血區，印刷廠就很難完全按照尺寸印刷封面。如果打印機只偏離了一點點，你的封面最終會在邊緣留下一個微小的、白色的、沒有印刷的邊緣。使用出血和修剪意味着你的封面每次都能看起來正確。</p><h3 id="在-scribus-中設置書籍的封面文檔" tabindex="-1">在 Scribus 中設置書籍的封面文檔 <a class="header-anchor" href="#在-scribus-中設置書籍的封面文檔" aria-label="Permalink to “在 Scribus 中設置書籍的封面文檔”">​</a></h3><p>要在 Scribus 中創建新文檔，請從定義文檔尺寸的<ruby>新文檔<rt>New Document</rt></ruby>對話框開始。單擊<ruby>出血<rt>Bleeds</rt></ruby>選項卡，並輸入 PDF 模板所説的出血尺寸。Lulu 圖書通常在所有邊緣使用 0.125 英寸的出血量。</p><p>對於 Scribus 中的文檔總尺寸，你不能只使用 PDF 模板上的文檔總尺寸。如果這樣做，你的 Scribus 文檔的尺寸會出現錯誤。相反，你需要做一些數學計算來獲取正確的尺寸。</p><p>看下 PDF 模板中的<ruby>文件總尺寸（含出血）<rt>Total Document Size (with bleed)</rt></ruby>。這是將要發送給打印機的 PDF 的總尺寸，它包括封底、書脊和封面（包含出血）。要在 Scribus 中輸入正確的尺寸，你必須從所有邊緣中減去出血。例如，我最新的書的尺寸是<ruby>四開本<rt>Crown Quarto</rt></ruby>，裝訂後尺寸為 7.44&quot; x 9.68&quot;，書脊寬度為 0.411&quot;。加上 0.125&quot; 的出血量，文件總尺寸（含出血）是 15.541&quot; × 9.93&quot;。因此，我在 Scribus 中的文檔尺寸是：</p><ul><li>寬：15.541-2 541-x 541-0.125=15.291&quot;</li><li>高：9.93-2 93-x 93-0.125=9.68&quot;</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/scribus-new-document.jpg" alt="Scribus document setup" title="Scribus document setup"></p><p>這將設置一個新的適合我的書的封面尺寸的 Scribus 文檔。新的 Scribus 文檔尺寸應與 PDF 模板上列出的“文件總尺寸（含出血）”完全匹配。</p><h3 id="從書脊開始" tabindex="-1">從書脊開始 <a class="header-anchor" href="#從書脊開始" aria-label="Permalink to “從書脊開始”">​</a></h3><p>在 Scribus 中創建新的書籍封面時，我喜歡從書脊區域開始。這可以幫助我驗證我是否在 Scribus 中正確定義了文檔。</p><p>使用<ruby>矩形<rt>Rectangle</rt></ruby>工具在文檔上繪製一個彩色方框，書脊需要出現在那裏。你不必完全按照正確的尺寸和位置來繪製，只要大小差不多並使用<ruby>屬性<rt>Properties</rt></ruby>來設置正確的值即可。在形狀的屬性中，選擇左上角基點，然後輸入書脊需要放在的 x、y 位置和尺寸。同樣，你需要做一些數學計算，並使用 PDF 模板上的尺寸作為參考。</p><p><img src="https://opensource.com/sites/default/files/uploads/scribus-empty-document.jpg" alt="Empty Scribus document" title="Empty Scribus document"></p><p>例如，我的書的修邊尺寸是 7.44&quot;×9.68&quot;，這是印刷廠修邊後的封面和封底的尺寸。我的書的書脊大小是 0.411&quot;，出血量是 0.125&quot;。也就是説，書脊的左上角 X、Y 的正確位置是：</p><ul><li>X 位置（出血量+裁剪寬度）：0.411+7.44=7.8510&quot;</li><li>Y 位置（減去出血量）：-0.125&quot;</li></ul><p>矩形的尺寸是我的書封面的全高（包括出血）和 PDF 模板中標明的書脊寬度。</p><ul><li>寬度：0.411&quot;</li><li>高度：9.93&quot;</li></ul><p>將矩形的<ruby>填充<rt>Fill</rt></ruby>設置為你喜歡的顏色，將<ruby>筆觸<rt>Stroke</rt></ruby>設置為<ruby>無<rt>None</rt></ruby>以隱藏邊界。如果你正確地定義了 Scribus 文檔，你應該最終得到一個矩形，它可以延伸到位於文檔中心的圖書封面的頂部和底部邊緣。</p><p><img src="https://opensource.com/sites/default/files/uploads/scribus-spine-rectangle.jpg" alt="Book spine in Scribus" title="Book spine in Scribus"></p><p>如果矩形與文檔不完全匹配，可能是你在創建 Scribus 文檔時設置了錯誤的尺寸。由於你還沒有在書的封面上花太多精力，所以可能最容易的做法是重新開始，而不是嘗試修復你的錯誤。</p><h3 id="剩下的就看你自己了" tabindex="-1">剩下的就看你自己了 <a class="header-anchor" href="#剩下的就看你自己了" aria-label="Permalink to “剩下的就看你自己了”">​</a></h3><p>接下來，你可以創建你的書的封面的其餘部分。始終使用 PDF 模板作為指導。封底在左邊，封面在右邊</p><p>我可以做一個簡單的書籍封面，但我缺乏藝術能力，無法創造出真正醒目的設計。在自己設計了幾個書的封面後，我對那些能設計出好封面的人產生了敬意。但如果你只是需要製作一個簡單的封面，你可以通過開源軟件自己動手。</p><hr>',32)),e("p",null,[t[9]||(t[9]=r("via: ",-1)),s(u,{href:"https://opensource.com/article/20/9/open-source-publishing-scribus"},{default:i(()=>[...t[8]||(t[8]=[r("https://opensource.com/article/20/9/open-source-publishing-scribus",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=r("作者：",-1)),s(u,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...t[10]||(t[10]=[r("Jim Hall",-1)])]),_:1}),t[15]||(t[15]=r(" 選題：",-1)),s(u,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[11]||(t[11]=[r("lujun9972",-1)])]),_:1}),t[16]||(t[16]=r(" 譯者：",-1)),s(u,{href:"https://github.com/geekpi"},{default:i(()=>[...t[12]||(t[12]=[r("geekpi",-1)])]),_:1}),t[17]||(t[17]=r(" 校對：",-1)),s(u,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=r("本文由 ",-1)),s(u,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[18]||(t[18]=[r("LCTT",-1)])]),_:1}),t[21]||(t[21]=r(" 原創編譯，",-1)),s(u,{href:"https://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[r("Linux中國",-1)])]),_:1}),t[22]||(t[22]=r(" 榮譽推出",-1))])])}const x=l(b,[["render",d]]);export{T as __pageData,x as default};
